  const rows = ITEMS.filter((i) => S.filter === 'all' || i.cat === S.filter).map((i, n) => {
    const inner = `<span><span>${t(i)}</span>${i.sub ? `<span class="sub">${esc(i.sub)}</span>` : ''}</span><span class="meta reg">${esc(i.reg)}</span><span class="meta">${esc(i.cat)}</span>`;
    return i.page ? `<a class="row" style="--i:${n}" href="/${esc(i.page)}">${inner}</a>` : `<div class="row dim" style="--i:${n}">${inner}</div>`;
  }).join('');
  return `<div class="chips">${chips}</div><div class="row head-row"><span>title</span><span class="reg">register</span><span>category</span></div>${rows}${ABOUT ? `<a class="row about" href="/${esc(ABOUT)}"><span>about</span><span class="reg"></span><span class="meta" aria-hidden="true">→</span></a>` : ''}`;
